INSERT INTO risk (risk_id, risk_code, title, description, category, department_id, owner_employee_id, status, identified_date, created_at, updated_at) VALUES
  (1, 'RSK-0001', 'Single-source dependency on resin supplier for Line 3', 'Line 3 moulding depends on one polymer grade from a single supplier with no qualified alternate. A supply interruption halts about 28% of plant output.', 'Operational', 4, 14, 'Mitigating', '2025-11-04', '2025-11-04 09:00:00', '2026-09-18 11:00:00'),
  (2, 'RSK-0002', 'Vendor payment approval bypass in ERP', 'Users holding both payment-create and payment-release roles can push vendor payments without a second approver, enabling error or fraud.', 'Compliance', 1, 1, 'Mitigating', '2025-11-10', '2025-11-10 09:00:00', '2026-08-20 11:00:00'),
  (3, 'RSK-0003', 'Expired ISO 27001 surveillance audit actions', 'Corrective actions raised in the ISO 27001 surveillance audit passed their due dates, putting certification at risk.', 'Compliance', 2, 5, 'Mitigating', '2025-11-12', '2025-11-12 09:00:00', '2026-07-10 11:00:00'),
  (4, 'RSK-0004', 'Phishing compromise of finance mailboxes', 'Targeted phishing against Accounts Payable and Treasury staff can lead to mailbox takeover, invoice redirection and payment fraud.', 'Technology', 2, 6, 'Mitigating', '2025-11-15', '2025-11-15 09:00:00', '2026-09-14 11:00:00'),
  (5, 'RSK-0005', 'Cold-storage temperature excursions at Jaipur DC', 'The Jaipur distribution centre cold room has a single refrigeration unit; excursions spoil temperature-sensitive stock and breach customer quality terms.', 'Operational', 4, 16, 'Mitigating', '2025-11-18', '2025-11-18 09:00:00', '2026-09-08 11:00:00'),
  (6, 'RSK-0006', 'Rupee depreciation on imported polymer feedstock', 'About 35% of raw material cost is USD-linked. Sharp INR depreciation compresses margin before price changes can be passed on.', 'Financial', 1, 1, 'Monitoring', '2025-11-20', '2025-11-20 09:00:00', '2026-05-19 11:00:00'),
  (7, 'RSK-0007', 'Unplanned downtime of Line 2 extrusion press', 'The Line 2 extrusion press is beyond its overhaul interval; failure would stop output and delay customer orders.', 'Operational', 3, 11, 'Mitigating', '2025-12-01', '2025-12-01 09:00:00', '2026-08-25 11:00:00'),
  (8, 'RSK-0008', 'GST input tax credit mismatches in GSTR-2B reconciliation', 'Supplier filing gaps cause input tax credit mismatches, leading to blocked credit and potential interest.', 'Compliance', 1, 4, 'Assessed', '2025-12-04', '2025-12-04 09:00:00', '2026-06-25 11:00:00'),
  (9, 'RSK-0009', 'Key-person dependency in plant maintenance', 'Three technicians hold nearly all knowledge of die changeover and press calibration; their absence delays recovery from faults.', 'Operational', 3, 9, 'Mitigating', '2025-12-08', '2025-12-08 09:00:00', '2026-10-05 11:00:00'),
  (10, 'RSK-0010', 'Unpatched legacy SCADA servers at Bhiwadi plant', 'SCADA servers run an unsupported operating system without vendor patches and are reachable from the corporate network.', 'Technology', 2, 8, 'Mitigating', '2025-12-12', '2025-12-12 09:00:00', '2026-09-30 11:00:00'),
  (11, 'RSK-0011', 'Non-compliance with Contract Labour (R&A) Act records', 'Wage registers and licence records for contract workers are incomplete for several principal contractors.', 'Compliance', 5, 18, 'Monitoring', '2026-01-05', '2026-01-05 09:00:00', '2026-07-20 11:00:00'),
  (12, 'RSK-0012', 'Attrition of skilled CNC operators', 'Skilled CNC operators are leaving for competitors, slowing throughput and raising rework.', 'Operational', 5, 17, 'Mitigating', '2026-01-08', '2026-01-08 09:00:00', '2026-09-29 11:00:00'),
  (13, 'RSK-0013', 'Customer concentration: top three distributors at 41% of revenue', 'Loss or renegotiation by any of the top three distributors would materially cut revenue.', 'Strategic', 7, 25, 'Assessed', '2026-01-12', '2026-01-12 09:00:00', '2026-08-10 11:00:00'),
  (14, 'RSK-0014', 'Delayed trade receivables from state dairy cooperatives', 'State cooperatives pay late, stretching working capital and increasing bad-debt exposure.', 'Financial', 7, 26, 'Mitigating', '2026-01-15', '2026-01-15 09:00:00', '2026-10-01 11:00:00'),
  (15, 'RSK-0015', 'Data privacy obligations under the DPDP Act not mapped', 'No data inventory or processing register exists for customer and employee personal data.', 'Compliance', 6, 21, 'Mitigating', '2026-01-20', '2026-01-20 09:00:00', '2026-06-18 11:00:00'),
  (16, 'RSK-0016', 'Fire safety system maintenance lapses at Neemrana warehouse', 'Fire pump tests and alarm maintenance at the Neemrana warehouse have been skipped, risking injury and insurance repudiation.', 'Operational', 8, 30, 'Mitigating', '2026-01-26', '2026-01-26 09:00:00', '2026-08-12 11:00:00'),
  (17, 'RSK-0017', 'Counterfeit product circulating in tier-2 markets', 'Counterfeit packs sold in tier-2 towns damage brand trust and expose customers to unsafe product.', 'Reputational', 7, 27, 'Monitoring', '2026-02-02', '2026-02-02 09:00:00', '2026-09-02 11:00:00'),
  (18, 'RSK-0018', 'Backup restoration never tested for ERP database', 'ERP database backups have not been restored in a test environment; recovery capability is unproven.', 'Technology', 2, 7, 'Mitigating', '2026-02-05', '2026-02-05 09:00:00', '2026-07-22 11:00:00'),
  (19, 'RSK-0019', 'Contract auto-renewal clauses unmanaged for logistics vendors', 'Auto-renewal clauses in logistics contracts roll over unnoticed, locking in unfavourable rates.', 'Compliance', 6, 24, 'Closed', '2026-02-09', '2026-02-09 09:00:00', '2026-06-10 11:00:00'),
  (20, 'RSK-0020', 'Monsoon flooding of Gurugram distribution yard', 'The Gurugram yard has no drainage outlet; waterlogging stops dispatch and damages stock.', 'Operational', 8, 31, 'Assessed', '2026-03-01', '2026-03-01 09:00:00', '2026-07-09 11:00:00'),
  (21, 'RSK-0021', 'Ransomware exposure through unmanaged contractor laptops', 'About 40 contractor laptops sit outside endpoint management and connect to plant and office networks.', 'Technology', 2, 6, 'Mitigating', '2026-03-10', '2026-03-10 09:00:00', '2026-09-21 11:00:00'),
  (22, 'RSK-0022', 'Inaccurate inventory valuation at third-party warehouses', 'Count variances at third-party warehouses distort inventory valuation and period-end results.', 'Financial', 1, 1, 'Assessed', '2026-03-15', '2026-03-15 09:00:00', '2026-06-20 11:00:00'),
  (23, 'RSK-0023', 'Pollution control board consent-to-operate renewal delay', 'Renewal of the Bhiwadi consent to operate takes about nine months; a lapse would stop production.', 'Compliance', 6, 23, 'Assessed', '2026-03-22', '2026-03-22 09:00:00', '2026-04-06 11:00:00'),
  (24, 'RSK-0024', 'Inbound freight cost volatility from diesel price spikes', 'Diesel price swings push freight cost above budget because most carrier rates float.', 'Financial', 4, 15, 'Monitoring', '2026-04-01', '2026-04-01 09:00:00', '2026-09-10 11:00:00'),
  (25, 'RSK-0025', 'Product recall readiness gaps', 'No mock recall exercise has been run in three years; batch traceability is untested.', 'Reputational', 3, 10, 'Mitigating', '2026-04-08', '2026-04-08 09:00:00', '2026-08-18 11:00:00'),
  (26, 'RSK-0026', 'Regional sales team misreporting rebate accruals', 'Rebate accruals are maintained manually by region and can be understated or overstated.', 'Financial', 7, 28, 'Assessed', '2026-04-15', '2026-04-15 09:00:00', '2026-04-29 11:00:00'),
  (27, 'RSK-0027', 'Social media backlash on packaging sustainability claims', 'Sustainability claims on packaging may be challenged as unsubstantiated, drawing public criticism.', 'Reputational', 7, 26, 'Identified', '2026-04-20', '2026-04-20 09:00:00', '2026-04-20 11:00:00'),
  (28, 'RSK-0028', 'Workplace injury at press shop from missing machine guarding', 'Three press-shop machines lack interlocked guards, exposing operators to serious injury.', 'Operational', 8, 30, 'Mitigating', '2026-03-20', '2026-03-20 09:00:00', '2026-09-03 11:00:00'),
  (29, 'RSK-0029', 'Insider access to payroll master data', 'Payroll master data can be edited by nine users without maker-checker control.', 'Technology', 5, 19, 'Assessed', '2026-05-04', '2026-05-04 09:00:00', '2026-08-05 11:00:00'),
  (30, 'RSK-0030', 'New competitor entry with import-parity pricing', 'An importer has announced an Indian plant and import-parity pricing, which may pressure our share.', 'Strategic', 7, 25, 'Monitoring', '2026-05-11', '2026-05-11 09:00:00', '2026-05-25 11:00:00'),
  (31, 'RSK-0031', 'Dependence on single freight forwarder for export shipments', 'One forwarder handles all export bookings and customs filings.', 'Operational', 4, 13, 'Assessed', '2026-05-18', '2026-05-18 09:00:00', '2026-08-02 11:00:00'),
  (32, 'RSK-0032', 'Capital project overrun on Bhiwadi Phase II expansion', 'The Phase II expansion is running over budget and behind schedule.', 'Strategic', 3, 9, 'Assessed', '2026-05-25', '2026-05-25 09:00:00', '2026-09-15 11:00:00'),
  (33, 'RSK-0033', 'Anti-bribery due diligence gaps for channel partners', 'Due diligence files are missing for a large share of channel partners.', 'Compliance', 6, 21, 'Mitigating', '2026-06-01', '2026-06-01 09:00:00', '2026-09-17 11:00:00'),
  (34, 'RSK-0034', 'Power failure at primary data room', 'A single UPS fed the primary data room, so a power event could take down core systems.', 'Technology', 2, 5, 'Closed', '2026-06-05', '2026-06-05 09:00:00', '2026-09-09 11:00:00'),
  (35, 'RSK-0035', 'Delayed statutory PF/ESI filings', 'Late provident fund and ESI filings attract penalties and interest.', 'Compliance', 5, 19, 'Closed', '2025-12-10', '2025-12-10 09:00:00', '2026-08-04 11:00:00'),
  (36, 'RSK-0036', 'Forex hedging policy not reviewed since 2024', 'The treasury hedging policy predates current exposures and limits.', 'Financial', 1, 1, 'Assessed', '2026-06-18', '2026-06-18 09:00:00', '2026-07-01 11:00:00'),
  (37, 'RSK-0037', 'Tooling obsolescence in Line 1 moulding', 'Line 1 moulds average eleven years in service, with two showing cracked cavities.', 'Strategic', 3, 10, 'Assessed', '2026-06-20', '2026-06-20 09:00:00', '2026-07-06 11:00:00'),
  (38, 'RSK-0038', 'Unauthorised visitor access at head-office reception', 'Visitors can reach office floors without badge control during peak hours.', 'Operational', 8, 32, 'Identified', '2026-09-01', '2026-09-01 09:00:00', '2026-09-01 11:00:00'),
  (39, 'RSK-0039', 'Weak supplier quality audit coverage', 'Fewer than a third of critical suppliers have had a quality audit in the past two years.', 'Operational', 4, 14, 'Identified', '2026-09-20', '2026-09-20 09:00:00', '2026-09-20 11:00:00'),
  (40, 'RSK-0040', 'Absence of a board-approved risk appetite statement', 'Risk tolerances are set informally by each function; the board has not approved an enterprise-wide appetite.', 'Strategic', 1, 2, 'Assessed', '2026-09-25', '2026-09-25 09:00:00', '2026-10-08 11:00:00');
