  (13, 4, 2, '2025-11-24', 4, 4, 'Two finance staff clicked simulated phishing links in the last drill.', '2025-11-24 11:00:00'),
  (14, 4, 5, '2025-12-20', 4, 5, 'Real compromise of an AP clerk mailbox on 3 December; MFA gaps found.', '2025-12-20 11:00:00'),
