  (19, 5, 16, '2026-05-12', 3, 4, NULL, '2026-05-12 11:00:00'),
  (20, 5, 12, '2026-09-08', 4, 4, 'Compressor trip on 5 September showed the standby unit does not auto-start.', '2026-09-08 11:00:00'),
  (21, 6, 2, '2025-12-02', 4, 3, NULL, '2025-12-02 11:00:00'),
  (22, 6, 1, '2026-03-17', 3, 3, 'Quarterly forward cover raised to 60% of forecast imports.', '2026-03-17 11:00:00'),
  (23, 6, 1, '2026-05-19', 3, 3, 'Natural hedge from export receivables covers about 40% of exposure.', '2026-05-19 11:00:00'),
  (24, 7, 12, '2025-12-10', 4, 4, 'Line 2 press has run 9,400 hours since overhaul against an 8,000 hour interval.', '2025-12-10 11:00:00'),
  (25, 7, 12, '2026-04-28', 5, 4, 'Gearbox failure on 20 April confirmed the overdue overhaul risk.', '2026-04-28 11:00:00'),
  (26, 7, 9, '2026-08-25', 3, 4, 'Gearbox replaced; condition-monitoring sensors being installed.', '2026-08-25 11:00:00'),
  (27, 8, 3, '2025-12-15', 3, 3, 'ITC mismatch averaged 2.3% of eligible credit in Q2 FY26.', '2025-12-15 11:00:00'),
  (28, 8, 4, '2026-03-26', 3, 2, 'Monthly vendor follow-up cut mismatches below 1.5%.', '2026-03-26 11:00:00'),
  (29, 8, 4, '2026-06-25', 2, 2, NULL, '2026-06-25 11:00:00'),
  (30, 9, 12, '2025-12-18', 4, 3, 'Three technicians hold all die changeover knowledge.', '2025-12-18 11:00:00'),
  (31, 9, 9, '2026-03-11', 4, 3, 'Standard work instructions drafted for the top ten changeovers.', '2026-03-11 11:00:00'),
  (32, 9, 9, '2026-05-14', 3, 3, 'Cross-training under way for two additional technicians.', '2026-05-14 11:00:00'),
  (33, 9, 9, '2026-10-05', 3, 2, NULL, '2026-10-05 11:00:00'),
  (34, 10, 2, '2025-12-22', 4, 5, 'SCADA servers run Windows Server 2012 R2 without vendor patches.', '2025-12-22 11:00:00'),
  (35, 10, 5, '2026-03-30', 5, 4, 'An exploit for the SCADA gateway software is now public.', '2026-03-30 11:00:00'),
  (36, 10, 2, '2026-09-30', 5, 4, 'Network segmentation done; OS upgrade deferred to the March shutdown.', '2026-09-30 11:00:00'),
  (37, 11, 23, '2026-01-14', 3, 4, 'Contractor wage and licence records incomplete for 3 of 9 principal contractors.', '2026-01-14 11:00:00'),
  (38, 11, 18, '2026-04-09', 3, 3, 'Two of three gaps closed; third contractor on notice.', '2026-04-09 11:00:00'),
  (39, 11, 23, '2026-07-20', 2, 3, 'Records now audited monthly.', '2026-07-20 11:00:00'),
  (40, 12, 2, '2026-01-20', 4, 3, 'Attrition of CNC operators at 22% annualised.', '2026-01-20 11:00:00'),
  (41, 12, 17, '2026-06-02', 4, 3, 'Retention bonus pilot launched at Bhiwadi.', '2026-06-02 11:00:00'),
  (42, 12, 17, '2026-08-11', 4, 3, NULL, '2026-08-11 11:00:00'),
  (43, 12, 17, '2026-09-29', 4, 4, 'Two resignations in August; a competitor is offering an 18% pay uplift.', '2026-09-29 11:00:00'),
