INSERT INTO incident (incident_id, incident_code, title, description, severity, status, department_id, reported_by, assigned_to, risk_id, occurred_at, reported_at, resolved_at) VALUES
  (1, 'INC-0001', 'Resin lot rejected on Line 3 for moisture content', 'Incoming resin lot from the sole supplier failed the moisture check at the Bhiwadi receiving lab; Line 3 had under two days of cover left.', 'High', 'Closed', 3, 10, 14, 1, '2025-11-06 14:20:00', '2025-11-06 15:50:00', '2025-11-09 03:50:00'),
  (2, 'INC-0002', 'Duplicate vendor invoice paid twice', 'Accounts Payable released two payments of ₹7.4 lakh against the same packaging vendor invoice submitted under different reference numbers.', 'Medium', 'Closed', 1, 4, 1, 2, '2025-11-19 09:05:00', '2025-11-19 14:05:00', '2025-11-22 17:05:00'),
  (3, 'INC-0003', 'Phishing compromise of AP clerk mailbox', 'The mailbox of an Accounts Payable clerk was taken over after a credential-harvesting email and used to send bank-detail change requests to three vendors.', 'Critical', 'Closed', 2, 6, 5, 4, '2025-12-03 16:45:00', '2025-12-03 18:45:00', '2025-12-07 14:45:00'),
  (4, 'INC-0004', 'Cold-storage temperature excursion at Jaipur DC', 'Cold-room temperature rose to 14°C for about five hours overnight after the compressor tripped; no alarm reached the shift supervisor.', 'High', 'Closed', 4, 16, 15, 5, '2025-12-14 02:10:00', '2025-12-14 08:10:00', '2025-12-18 05:10:00'),
  (5, 'INC-0005', 'Tailgating observed at head-office reception', 'A contractor without a badge followed an employee through the turnstile and reached the third floor before being challenged.', 'Low', 'Closed', 8, 32, 29, NULL, '2025-12-29 11:30:00', '2025-12-29 12:30:00', '2025-12-30 18:30:00'),
  (6, 'INC-0006', 'Hydraulic leak on Line 2 press', 'Hydraulic oil leaked from the main ram seal on the Line 2 press, forcing an emergency stop during the morning shift.', 'Medium', 'Closed', 3, 11, 11, 7, '2026-01-12 07:40:00', '2026-01-12 08:10:00', '2026-01-13 09:10:00'),
  (7, 'INC-0007', 'Late PF challan attracts interest and penalty', 'The December provident fund challan was paid four days after the due date, creating interest and a penalty notice.', 'High', 'Closed', 5, 19, 18, 35, '2026-01-27 13:15:00', '2026-01-27 16:15:00', '2026-01-30 00:15:00'),
  (8, 'INC-0008', 'Auto-renewal of transport contract missed', 'The annual contract with a regional transporter renewed automatically at a 6% higher rate because the notice window was missed.', 'Medium', 'Closed', 6, 24, 23, 19, '2026-02-09 10:00:00', '2026-02-10 10:00:00', '2026-02-12 21:00:00'),
  (9, 'INC-0009', 'Fire alarm panel fault at Neemrana warehouse', 'The fire alarm panel at Neemrana showed a persistent fault for three days before the AMC vendor attended.', 'High', 'Closed', 8, 31, 30, 16, '2026-02-21 18:25:00', '2026-02-21 22:25:00', '2026-02-24 14:25:00'),
  (10, 'INC-0010', 'ERP database restore test failed', 'The first scheduled restore of the ERP database to the test server failed with a corrupted log chain.', 'Medium', 'Closed', 2, 8, 7, 18, '2026-03-05 08:50:00', '2026-03-05 10:50:00', '2026-03-08 08:50:00'),
  (11, 'INC-0011', 'Rebate claim keyed with wrong customer code', 'A ₹2.8 lakh rebate for a Pune distributor was posted against a Nashik customer code.', 'Low', 'Closed', 7, 28, 25, NULL, '2026-03-18 15:35:00', '2026-03-19 11:35:00', '2026-03-20 18:35:00'),
  (12, 'INC-0012', 'Operator laceration at press shop', 'An operator suffered a finger laceration while clearing a jam on an unguarded press; first aid given and a hospital visit followed.', 'High', 'Resolved', 3, 10, 9, 28, '2026-04-02 12:00:00', '2026-04-02 13:00:00', '2026-04-08 04:00:00'),
  (13, 'INC-0013', 'Gearbox failure stops Line 2 for 52 hours', 'The Line 2 extrusion press gearbox seized mid-shift, stopping production for 52 hours and delaying 14 customer orders.', 'Critical', 'Resolved', 3, 11, 9, 7, '2026-04-20 06:15:00', '2026-04-20 06:45:00', '2026-04-23 00:45:00'),
  (14, 'INC-0014', 'Counterfeit packs found in Nagpur retail', 'A field sales officer found counterfeit packs of a top-selling SKU in three Nagpur retail outlets.', 'Medium', 'Resolved', 7, 27, 26, 17, '2026-05-08 14:40:00', '2026-05-08 22:40:00', '2026-05-14 05:40:00'),
  (15, 'INC-0015', 'Malware beaconing from contractor laptop', 'Network monitoring flagged outbound command-and-control beaconing from a contractor laptop connected to the Bhiwadi office network.', 'High', 'Resolved', 2, 6, 5, 21, '2026-05-26 09:30:00', '2026-05-26 10:30:00', '2026-05-28 12:30:00'),
  (16, 'INC-0016', 'Inventory count variance at Bhiwandi 3PL', 'The June cycle count at the Bhiwandi third-party warehouse found a stock shortfall valued at ₹19.2 lakh.', 'Medium', 'Resolved', 1, 4, 1, 22, '2026-06-09 17:10:00', '2026-06-10 23:10:00', '2026-06-18 06:10:00'),
  (17, 'INC-0017', 'Payroll cut-off missed for 14 contract workers', 'Attendance for 14 contract workers at Bhiwadi was submitted after the payroll cut-off and left out of the June run.', 'Low', 'Resolved', 5, 18, 17, NULL, '2026-06-23 10:20:00', '2026-06-23 13:20:00', '2026-06-24 17:20:00'),
  (18, 'INC-0018', 'Monsoon waterlogging at Gurugram yard', 'Heavy rain flooded the Gurugram distribution yard to 30 cm; six trucks were delayed by up to 14 hours.', 'High', 'Resolved', 8, 32, 31, 20, '2026-07-07 03:55:00', '2026-07-07 05:55:00', '2026-07-09 06:55:00'),
  (19, 'INC-0019', 'ERP database unavailable for four hours', 'A storage controller fault took the ERP database offline for four hours, stopping order entry and warehouse dispatch.', 'Critical', 'Contained', 2, 8, 7, 18, '2026-07-15 13:45:00', '2026-07-15 14:15:00', NULL),
  (20, 'INC-0020', 'Export containers held at Mundra for documentation error', 'Three export containers were held at Mundra port after the forwarder filed the wrong HS code on the shipping bill.', 'High', 'Contained', 4, 15, 13, 31, '2026-07-29 11:05:00', '2026-07-29 15:05:00', NULL),
  (21, 'INC-0021', 'Channel partner onboarded without anti-bribery declaration', 'A Lucknow channel partner received supplies for two months without a signed anti-bribery declaration on file.', 'Medium', 'Contained', 6, 24, 21, 33, '2026-08-06 09:15:00', '2026-08-08 09:15:00', NULL),
  (22, 'INC-0022', 'Cracked Line 1 mould forces borrowed tooling', 'A mould cavity cracked on Line 1; a backup tool was borrowed from the Bhiwadi Phase I stores at reduced cycle speed.', 'High', 'Contained', 3, 10, 9, 37, '2026-08-14 16:30:00', '2026-08-14 17:30:00', NULL),
  (23, 'INC-0023', 'Two CNC operators resign in the same week', 'Two senior CNC operators resigned on consecutive days to join a competitor, leaving the night shift short.', 'Medium', 'Contained', 5, 20, 17, 12, '2026-08-24 08:20:00', '2026-08-24 14:20:00', NULL),
  (24, 'INC-0024', 'Payment released without second approver', 'ERP flagged a ₹18.6 lakh vendor payment released by a single user holding both create and release roles.', 'High', 'Investigating', 1, 4, 2, 2, '2026-09-01 12:40:00', '2026-09-01 15:40:00', NULL),
  (25, 'INC-0025', 'Cold-room compressor trip at Jaipur DC', 'The cold-room compressor tripped at Jaipur DC and the temperature reached 11°C for three hours before the standby unit was started by hand.', 'Medium', 'Investigating', 4, 16, 15, 5, '2026-09-05 10:10:00', '2026-09-05 13:10:00', NULL),
  (26, 'INC-0026', 'OAuth consent phishing against Treasury executive', 'A Treasury executive granted a malicious application access to mail and files after a convincing consent-request email.', 'Critical', 'Investigating', 2, 6, 5, 4, '2026-09-11 15:00:00', '2026-09-11 20:00:00', NULL),
  (27, 'INC-0027', 'Eyewash station inoperative in chemical store', 'The emergency eyewash station in the chemical store at Bhiwadi was found with no water supply during a routine check.', 'Medium', 'Resolved', 8, 30, 30, NULL, '2026-09-16 09:50:00', '2026-09-16 10:50:00', '2026-09-24 21:50:00'),
  (28, 'INC-0028', 'Customer data export sent to wrong vendor address', 'A customer contact export was emailed to an outdated address at an external analytics vendor.', 'High', 'Investigating', 6, 23, 22, 15, '2026-09-22 14:25:00', '2026-09-23 10:25:00', NULL),
  (29, 'INC-0029', 'Rebate accrual discrepancy in West region', 'The West region rebate accrual is ₹4.2 lakh lower than the sum of signed rebate letters.', 'Low', 'Resolved', 7, 28, 25, 26, '2026-09-28 11:15:00', '2026-09-29 11:15:00', '2026-10-02 06:15:00'),
  (30, 'INC-0030', 'Preventive maintenance skipped on Line 4', 'The monthly preventive maintenance on Line 4 was skipped because the maintenance supervisor was on leave with no named delegate.', 'Medium', 'Investigating', 3, 11, NULL, 9, '2026-10-02 07:30:00', '2026-10-03 13:30:00', NULL),
  (31, 'INC-0031', 'Resin supplier delays shipment by nine days', 'The resin supplier reported a nine-day delay after vessel rollover; Line 3 buffer stands at 12 days.', 'High', 'Investigating', 4, 14, 13, 1, '2026-10-06 18:00:00', '2026-10-06 22:00:00', NULL),
  (32, 'INC-0032', 'Visitor Wi-Fi bridged to corporate VLAN', 'A vulnerability scan showed the visitor Wi-Fi at the Gurugram office can reach corporate servers.', 'Medium', 'Open', 2, 32, NULL, NULL, '2026-10-09 10:45:00', '2026-10-11 10:45:00', NULL),
  (33, 'INC-0033', 'Repeated false alarms from Neemrana smoke detectors', 'Zone C smoke detectors at Neemrana triggered four false alarms in a week, and staff have begun to ignore evacuation calls.', 'High', 'Open', 8, 31, NULL, 16, '2026-10-12 13:20:00', '2026-10-12 19:20:00', NULL),
  (34, 'INC-0034', 'Biometric attendance sync failures at Bhiwadi', 'The biometric devices at Bhiwadi have failed to sync to HR software on five days, causing manual attendance corrections.', 'Low', 'Open', 5, 18, 19, NULL, '2026-10-15 09:10:00', '2026-10-15 14:10:00', NULL),
  (35, 'INC-0035', 'Unhedged USD exposure above policy limit', 'Treasury identified an unhedged USD payable position of USD 410,000, above the 25% policy limit.', 'Medium', 'Open', 1, 1, 2, 36, '2026-10-17 16:05:00', '2026-10-17 18:05:00', NULL),
  (36, 'INC-0036', 'Broken seals on inbound shipment at Jaipur DC', 'Seals were broken on a consignment of finished-good cartons from a contract manufacturer when it arrived at Jaipur DC.', 'High', 'Open', 4, 16, 13, NULL, '2026-10-19 08:40:00', '2026-10-19 10:40:00', NULL);
